import{i as e,o as t,r as n,t as r}from"./app-DoYG-hoA.js";var i=JSON.parse(`{"path":"/docs/dvns/%E8%AF%AD%E6%B3%95.html","title":"dvns 语法","lang":"zh-CN","frontmatter":{"description":"说明 Dvnge 剧本语法 dvns 的完整写法，包括节点、指令、对话、选项、变量等所有可用语法。"},"filePathRelative":"docs/dvns/语法.md","git":{"createdTime":1791969142000,"updatedTime":1791969142000,"contributors":[{"name":"TTQWNTian","username":"TTQWNTian","email":"ttqwntian@qq.com","commits":1,"url":"https://github.com/TTQWNTian"}]}}`),a={name:`语法.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="dvns-语法" tabindex="-1"><a class="header-anchor" href="#dvns-语法"><span>dvns 语法</span></a></h1><p>本章介绍 Dvnge 的独创语法：<strong>dvns</strong>。</p><p><code>.dvns</code> 放在 <code>chapter/</code> 目录下，一个文件就是一个章节。整份剧本由若干「节点」组成，节点之间用 <code>$</code> 分隔。</p><h2 id="节点" tabindex="-1"><a class="header-anchor" href="#节点"><span>节点</span></a></h2><p>一个节点就是一段对话加上它携带的所有指令。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@背景 #fff</span>
<span class="line">&quot;Tian&quot;: 你好，世界。$</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>上面这段就是一个节点：</p><ul><li><code>@背景 #fff</code> 设置背景</li><li><code>&quot;Tian&quot;: 你好，世界。</code> 是对话</li></ul><p>每个节点之间用 <code>$</code> 分隔：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">&quot;Tian&quot;: 你好，世界。$</span>
<span class="line">&quot;Tian&quot;: 欢迎使用Dvnge~$</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>运行游戏，点击一下屏幕就切换到下一个节点。</p><div class="hint-container warning"><p class="hint-container-title">每个节点末尾必须加 <code>$</code>。</p></div><h2 id="对话" tabindex="-1"><a class="header-anchor" href="#对话"><span>对话</span></a></h2><p>格式是 <code>&quot;角色名&quot;: 内容</code> 。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">&quot;Tian&quot;: 你好，欢迎使用Dvnge。$</span>
<span class="line">这是没有角色的旁白$</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>角色名显示在对话框左上角，可以留空。</li><li>内容支持任意 <strong>HTML</strong> 标签，比如 <code>&lt;b&gt;粗体&lt;/b&gt;</code>、<code>&lt;i&gt;斜体&lt;/i&gt;</code>、<code>&lt;br&gt;</code>，甚至<code>&lt;button&gt;按钮&lt;/button&gt;</code>。</li><li>内容支持变量插值，用 <code>{变量名}</code> 引用用户变量。</li></ul><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">&quot;Tian&quot;: 你好，{name}！你现在有 {金币} 块金币。$</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>变量不存在时会替换为“未知”。支持嵌套变量：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">&quot;Tian&quot;: 当前血量 {玩家.血量}。$</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>如果想在对话里加特殊效果，也可以直接写 <strong>HTML</strong>：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">&quot;Tian&quot;: &lt;span style=&#39;color:red;&#39;&gt;今天的天气真好啊。&lt;/span&gt;$</span>
<span class="line">// 也可以使用 class</span>
<span class="line">&quot;Tian&quot;: &lt;span class=&#39;highlight&#39;&gt;是适合使用Dvnge制作视觉小说的日子&lt;/span&gt;$</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="指令" tabindex="-1"><a class="header-anchor" href="#指令"><span>指令</span></a></h2><p>所有指令以 <code>@</code> 开头，参数之间用英文逗号 <code>,</code> 分隔，键值对用 <code>=</code> 连接。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@指令名 参数1, 键1=值1, 键2=值2</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="背景" tabindex="-1"><a class="header-anchor" href="#背景"><span>背景</span></a></h2><p>设置背景，支持纯色、图片、视频。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@背景 #fff</span>
<span class="line">@背景 assets/bg/room.png</span>
<span class="line">@背景 assets/bg/opening.mp4</span>
<span class="line">@背景 null</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>#fff</code>：纯色背景</li><li>带扩展名的路径：图片或视频背景</li><li><code>null</code>：清空背景为黑色</li></ul><p>视频背景可以用 <code>@背景媒体</code> 控制播放：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@背景 media/opening.mp4</span>
<span class="line">@背景媒体 循环=true, 播放次数=1, 播放间隔=0, 音量=0.8</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="音乐" tabindex="-1"><a class="header-anchor" href="#音乐"><span>音乐</span></a></h2><p>播放背景音乐，默认循环，切换时会淡出。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@音乐 assets/bgm/theme.mp3</span>
<span class="line">@音乐 assets/bgm/theme.mp3, 循环=true, 音量=0.7, 淡出=1000</span>
<span class="line">@音乐 null</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>null</code>：停止当前音乐</li><li><code>淡出</code>：淡出时间，单位毫秒</li></ul><h2 id="音效" tabindex="-1"><a class="header-anchor" href="#音效"><span>音效</span></a></h2><p>播放一次性音效，可以和音乐同时播放。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@音效 assets/se/click.mp3</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="立绘" tabindex="-1"><a class="header-anchor" href="#立绘"><span>立绘</span></a></h2><p>控制左、中、右三个位置的立绘。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@立绘 左, assets/char/tian.png</span>
<span class="line">@立绘 中, assets/char/tian.png, 淡入=500</span>
<span class="line">@立绘 右, 角色名, 预设名</span>
<span class="line">@立绘 左, false</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>第一个参数是位置：<code>左</code>、<code>中</code>、<code>右</code></li><li>第二个参数是图片/视频路径，或角色名（配合预设）</li><li>第三个参数是预设名，可选</li><li><code>false</code>：隐藏该位置立绘</li></ul><p>视频立绘可以用 <code>@立绘媒体</code> 控制播放：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@立绘 中, media/char.mp4</span>
<span class="line">@立绘媒体 中, 循环=true, 播放次数=1, 播放间隔=0, 音量=0.5</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="头像" tabindex="-1"><a class="header-anchor" href="#头像"><span>头像</span></a></h2><p>显示在对话框左边或右边的头像。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@头像 assets/avatar/tian.png</span>
<span class="line">@头像 assets/avatar/tian.png, 位置=左</span>
<span class="line">@头像 assets/avatar/tian.png, 位置=右</span>
<span class="line">@头像 null</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>不写 <code>位置</code> 默认左。<code>null</code> 表示隐藏头像。</p><h2 id="标题" tabindex="-1"><a class="header-anchor" href="#标题"><span>标题</span></a></h2><p>在屏幕上显示标题文字。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@标题 第一章</span>
<span class="line">@标题 第一章, 位置=中</span>
<span class="line">@标题 第一章, 位置=左上</span>
<span class="line">@标题 第一章, 位置=中, 样式=color:#fff;font-size:48px</span>
<span class="line">// 要使用class，这样写：</span>
<span class="line">@标题 第一章, 位置=中, 样式=title-highlight</span>
<span class="line">@标题 false</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>位置支持：<code>上</code>、<code>下</code>、<code>左</code>、<code>右</code>、<code>左上</code>、<code>左下</code>、<code>右上</code>、<code>右下</code>、<code>中</code>。</p><h2 id="设置变量" tabindex="-1"><a class="header-anchor" href="#设置变量"><span>设置变量</span></a></h2><p>设置用户变量。格式是 <code>&quot;变量名&quot;</code> 值，多个变量用逗号分隔。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@设置变量 &quot;好感&quot; +1, &quot;金币&quot; 100</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>值支持：</p><ul><li>数字：100、3.14、-5</li><li>字符串：不用加引号直接写</li><li>运算：+1、-1、*2、/2，表示在当前值上运算</li></ul><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@设置变量 &quot;好感&quot; +1</span>
<span class="line">@设置变量 &quot;金币&quot; -50</span>
<span class="line">@设置变量 &quot;等级&quot; *2</span>
<span class="line">@设置变量 &quot;血量&quot; /2</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>嵌套变量用 <code>.</code>：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@设置变量 &quot;进度.第一章&quot; 1</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="读档时设置变量" tabindex="-1"><a class="header-anchor" href="#读档时设置变量"><span>读档时设置变量</span></a></h2><p>只在读档时应用，用于根据存档状态做特殊处理。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@读档时设置变量 &quot;回档&quot; true</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="输入" tabindex="-1"><a class="header-anchor" href="#输入"><span>输入</span></a></h2><p>显示输入框，玩家输入存入用户变量。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@输入 name</span>
<span class="line">@输入 name, 占位符=请输入, 提示文字=你的名字, 按钮文字=确认, 最大长度=20, 必填=true</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>第一个参数是变量名，必填</li><li><code>占位符</code>：输入框内灰字提示</li><li><code>提示文字</code>：输入框上方文字</li><li><code>按钮文字</code>：确认按钮文字</li><li><code>最大长度</code>：数字</li><li><code>必填</code>：<code>true</code> 或 <code>false</code></li></ul><p>翻译文件里可以省略变量名：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@输入 占位符=Enter here,提示文字=Enter your name,按钮文字=Confirm</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="选项" tabindex="-1"><a class="header-anchor" href="#选项"><span>选项</span></a></h2><p>分支选项。单独一行写 <code>@选项</code>，之后每一行是一个选项。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@选项</span>
<span class="line">是 -&gt; 喜欢</span>
<span class="line">否 -&gt; 讨厌$</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>选项文本 -&gt; 目标</code>，目标是标签名或节点索引</li><li>不写 <code>-&gt;</code>：选中后进入下一个节点</li></ul><p>带属性：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@选项</span>
<span class="line">是 -&gt; 喜欢, 设置变量=&quot;好感&quot; +1</span>
<span class="line">否 -&gt; 讨厌, 设置变量=&quot;好感&quot; -1</span>
<span class="line">也许 -&gt; 喜欢, 条件=好感 &gt;= 5, 否则=讨厌</span>
<span class="line">隐藏 -&gt; 隐藏结局, 条件=好感 &gt;= 10, 解锁CG=结局CG</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>支持的属性：</p><ul><li><code>设置变量</code>：选中后设置变量</li><li><code>条件</code>：<strong>JavaScript</strong> 表达式，为假时该选项默认不显示；如果同时写了 <code>否则</code>，则不隐藏，点击后跳转到 <code>否则</code> 目标</li><li><code>否则</code>：条件为假时的跳转目标</li><li><code>解锁CG</code>：选中后解锁指定 <strong>CG</strong></li><li><code>样式</code>：选项按钮的 <strong>CSS</strong></li></ul><h2 id="目标" tabindex="-1"><a class="header-anchor" href="#目标"><span>目标</span></a></h2><p>跳转到指定位置。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@目标 5</span>
<span class="line">@目标 标签名</span>
<span class="line">@目标 标签名, 章节=第二章</span>
<span class="line">@目标 索引, 章节=第二章</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>数字：跳到当前章节的节点索引</li><li>字符串：跳到当前章节的标签</li><li>带 <code>章节</code>：跳到指定章节</li></ul><h2 id="标签" tabindex="-1"><a class="header-anchor" href="#标签"><span>标签</span></a></h2><p>给节点设置标签，供 <code>@目标</code> 跳转。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@标签 喜欢</span>
<span class="line">&quot;Tian&quot;: 我喜欢你~$</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="条件" tabindex="-1"><a class="header-anchor" href="#条件"><span>条件</span></a></h2><p>根据条件跳转。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@条件 好感 &gt;= 10, 真=好结局, 假=坏结局</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>第一个参数：<strong>JavaScript</strong> 表达式</li><li><code>真</code>：条件为真时跳转的目标</li><li><code>假</code>：条件为假时跳转的目标</li></ul><p>表达式里可以直接用变量名：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@条件 金币 &gt; 100 &amp;&amp; 等级 &gt;= 5, 真=购买成功, 假=金币不足</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>读嵌套变量用 getVar：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@条件 getVar(&#39;玩家.血量&#39;) === 100, 真=继续, 假=重玩</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>可在对话、选项、路径、标题里使用 <code>{变量名}</code>：</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">&quot;Tian&quot;: 你好，{name}！</span>
<span class="line">@背景 assets/bg/{场景}.png</span>
<span class="line">@标题 第{章节}章</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="自动存档" tabindex="-1"><a class="header-anchor" href="#自动存档"><span>自动存档</span></a></h2><p>在当前节点触发自动存档。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@自动存档</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="自动节点" tabindex="-1"><a class="header-anchor" href="#自动节点"><span>自动节点</span></a></h2><p>等待指定秒数后自动推进。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@自动节点 1.5</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="解锁cg" tabindex="-1"><a class="header-anchor" href="#解锁cg"><span>解锁CG</span></a></h2><p>解锁一张 <strong>CG</strong> 到收藏库。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@解锁CG 结局CG, assets/cg/ending.png</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="调查" tabindex="-1"><a class="header-anchor" href="#调查"><span>调查</span></a></h2><p>进入调查模式，玩家点击指定区域触发跳转。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@调查 光标=pointer, 返回=返回标签</span>
<span class="line">区域 x=100, y=200, 宽=300, 高=200, 目标=抽屉, 贴图=assets/ui/drawer.png</span>
<span class="line">区域 x=500, y=300, 宽=200, 高=200, 目标=窗户</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>光标</code>：<strong>CSS</strong> 光标，如 <code>pointer</code>、<code>crosshair</code></li><li><code>返回</code>：点击返回按钮时跳转的目标</li><li><code>区域</code>：可点击区域，多区域写多行</li></ul><h2 id="跳转html" tabindex="-1"><a class="header-anchor" href="#跳转html"><span>跳转HTML</span></a></h2><p>跳转到其他 <strong>HTML</strong> 页面，可传参和传变量。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@跳转HTML index.html</span>
<span class="line">@跳转HTML index.html, 参数=page=1</span>
<span class="line">@跳转HTML index.html, 传递变量=name,金币</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="逐字显示" tabindex="-1"><a class="header-anchor" href="#逐字显示"><span>逐字显示</span></a></h2><p>控制文本的逐字显示，可在 <code>js/游戏配置.js</code> 修改默认设置。<code>速度</code>单位为秒，越小越快。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@逐字显示 速度=0.02</span>
<span class="line">@逐字显示 false </span>
<span class="line">// 或 true</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="打字音效" tabindex="-1"><a class="header-anchor" href="#打字音效"><span>打字音效</span></a></h2><p>逐字显示时播放音效，同样可在 <code>js/游戏配置.js</code> 中修改默认设置。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@打字音效 assets/se/type.mp3, 音量=0.5, 间隔=3</span>
<span class="line">@打字音效 false </span>
<span class="line">// 或 true</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="快进" tabindex="-1"><a class="header-anchor" href="#快进"><span>快进</span></a></h2><p>控制快进模式。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@快进 true</span>
<span class="line">@快进 false</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="自定义功能" tabindex="-1"><a class="header-anchor" href="#自定义功能"><span>自定义功能</span></a></h2><p>执行自定义 <strong>JavaScript</strong> 代码。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@自定义功能 弹窗(&#39;你好&#39;)</span>
<span class="line">@自定义功能 console.log(&#39;调试&#39;)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="动画" tabindex="-1"><a class="header-anchor" href="#动画"><span>动画</span></a></h2><p>给指定元素应用 <strong>CSS</strong> 动画。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">@动画 对话框=对话框进入动画 0.3s ease</span>
<span class="line">@动画 内容=颤抖 0.5s</span>
<span class="line">@动画 左立绘=淡入 0.3s</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可设置动画的内容：<code>左立绘</code>、<code>中立绘</code>、<code>右立绘</code>、<code>背景</code>、<code>对话框</code>、<code>角色</code>、<code>内容</code>、<code>头像</code>。</p><h2 id="特殊标签" tabindex="-1"><a class="header-anchor" href="#特殊标签"><span>特殊标签</span></a></h2><ul><li><code>&lt;wait=1.5&gt;</code>：等待 1.5 秒后继续逐字显示</li></ul><h2 id="注释" tabindex="-1"><a class="header-anchor" href="#注释"><span>注释</span></a></h2><p>以 <code>//</code> 开头的行会被忽略。</p><div class="language-dvns line-numbers-mode" data-highlighter="prismjs" data-ext="dvns"><pre><code class="language-dvns"><span class="line">// 这是注释</span>
<span class="line">&quot;Tian&quot;: 你好$</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>注释只能整行，不能行尾。</p>`,131)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};